  ('1e3a8767-211d-5934-8907-4dfe1ef39f24', '00000000-0000-4000-a000-000000000001', 'Irish Coffee', 'stirred', '', '', 'Warm black coffee is poured into a pre-heated Irish coffee glass. Whiskey and at least one teaspoon of sugar is added and stirred until dissolved. Fresh thick chilled cream is carefully poured over the back of a spoon held just above the surface of the coffee. The layer of cream will float on the coffee without mixing. Plain sugar can be replaced with sugar syrup', '[{"name":"Irish Whiskey","amount_ml":50,"original_amount":50,"original_unit":"ml","type":"spirit","catalogue_id":"47c28046-b7ca-5a1a-adb5-39f74be91762","abv":40,"cost_per_ml_at_publish":null,"note":null},{"name":"Hot coffee","amount_ml":120,"original_amount":120,"original_unit":"ml","type":"other","catalogue_id":"78f3fc0a-e435-54ed-8695-bba3df0398fa","abv":0,"cost_per_ml_at_publish":null,"note":null},{"name":"Fresh cream","amount_ml":50,"original_amount":50,"original_unit":"ml","type":"other","catalogue_id":"7d18395e-b0f1-54c1-87e4-b94b2be9fbb2","abv":0,"cost_per_ml_at_publish":null,"note":"Chilled"},{"name":"Sugar","amount_ml":1,"original_amount":1,"original_unit":"teaspoon","type":"sweetener","catalogue_id":"789958ff-94d0-5ef1-a1db-0a5f4eb3b38a","abv":0,"cost_per_ml_at_publish":null,"note":null}]'::jsonb, null, null),
